import androidx.compose.foundation.lazy.items
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.ExtendedFloatingActionButton
import androidx.compose.material3.HorizontalDivider
import androidx.compose.material3.ListItem
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.material3.TextButton
import androidx.compose.material3.TopAppBar
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.navigation.NavController
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import dev.ohs.fhir.datacapture.Questionnaire
import dev.ohs.fhir.engine.FhirEngineProvider
import dev.ohs.fhir.engine.get
import dev.ohs.fhir.model.r4.Patient
import kotlin.coroutines.cancellation.CancellationException
import kotlinx.coroutines.launch

class MainActivity : ComponentActivity() {
  private val sync: SyncViewModel by viewModels()

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        val nav = rememberNavController()
        val syncState by sync.syncState.collectAsState()
        NavHost(nav, startDestination = "register") {
          composable("register") { RegisterScreen(nav, syncState, sync::syncNow) }
          composable("patient/{id}") { PatientScreen(nav, it.arguments!!.getString("id")!!, syncState) }
          // Own destination = own ViewModelStoreOwner, so each new visit starts with a blank form.
          composable("visit/{id}") { VisitFormScreen(nav, it.arguments!!.getString("id")!!, sync::syncNow) }
        }
      }
    }
  }
}

@Composable
private fun engine() = FhirEngineProvider.getInstance(androidx.compose.ui.platform.LocalContext.current.applicationContext)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun RegisterScreen(nav: NavController, syncState: String?, onSync: () -> Unit) {
  val engine = engine()
  var rows by remember { mutableStateOf<List<PatientRow>?>(null) }
  LaunchedEffect(syncState) { rows = engine.loadRegister() }
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("ANC Register") },
        actions = { TextButton(onClick = onSync) { Text(syncState ?: "Sync") } },
      )
    }
  ) { pad ->
    val list = rows
    when {
      list == null -> Box(Modifier.padding(pad).padding(16.dp)) { Text("Loading…") }
      list.isEmpty() -> Box(Modifier.padding(pad).padding(16.dp)) { Text("No patients yet. ${syncState ?: ""}") }
      else -> LazyColumn(Modifier.padding(pad)) {
        items(list, key = { it.id }) { p ->
          ListItem(
            modifier = Modifier.clickable { nav.navigate("patient/${p.id}") },
            headlineContent = { Text(p.name) },
            supportingContent = {
              Text("Age ${p.age ?: "?"} · Due ${p.dueDate ?: "unknown"} · ${p.weeks?.let { "$it weeks" } ?: "GA unknown"}")
            },
          )
          HorizontalDivider()
        }
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun PatientScreen(nav: NavController, patientId: String, syncState: String?) {
  val engine = engine()
  var name by remember { mutableStateOf("") }
  var visits by remember { mutableStateOf<List<Visit>?>(null) }
  LaunchedEffect(syncState) {
    name = runCatching { engine.get<Patient>(patientId).displayName() }.getOrDefault("")
    visits = engine.loadVisits(patientId)
  }
  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text(name) },
        navigationIcon = { TextButton(onClick = { nav.popBackStack() }) { Text("Back") } },
      )
    },
    floatingActionButton = {
      ExtendedFloatingActionButton(onClick = { nav.navigate("visit/$patientId") }) { Text("Record visit") }
    },
  ) { pad ->
    val list = visits
    when {
      list == null -> Box(Modifier.padding(pad).padding(16.dp)) { Text("Loading…") }
      list.isEmpty() -> Box(Modifier.padding(pad).padding(16.dp)) { Text("No visits recorded.") }
      else -> LazyColumn(Modifier.padding(pad)) {
        item { Text("ANC visits", Modifier.padding(16.dp), style = MaterialTheme.typography.titleMedium) }
        items(list) { v ->
          ListItem(
            headlineContent = { Text(v.date) },
            supportingContent = {
              Column {
                Text("Weight: ${v.weight?.let { "$it kg" } ?: "—"}")
                Text("BP: ${v.bp?.let { "$it mmHg" } ?: "—"}")
                v.hb?.let { Text("Hb: $it g/dL") }
